import unittest
from retry.policy import retry_call, MaxRetriesExceededError

class TestRetry(unittest.TestCase):
    def test_retry_success(self):
        cnt = [0]
        def flaky():
            cnt[0] += 1
            if cnt[0] < 2: raise ValueError('boom')
            return 42
        self.assertEqual(retry_call(flaky, max_retries=3), 42)

if __name__ == '__main__': unittest.main()

